arguments.command:
python -c "
from glom import glom, T, Auto, Fill, Invoke, Iter, Let, ROOT, Literal

# Test Auto
target = {'a': 1}
print('Auto test:', glom(target, Auto('a')))  # Should be 1

# Test Fill
target = {'a': 1}
result = glom(target, Fill({'a': 'a', 'b': Literal('default')}))
print('Fill test:', result)  # Should be {'a': 1, 'b': 'default'}

# Test Invoke
class Example:
    def add(self, x, y):
        return x + y
target = Example()
result = glom(target, Invoke('add', args=[1, 2]))
print('Invoke test:', result)  # Should be 3

# Test Iter
target = [1, 2, 3, 4]
result = glom(target, Iter(lambda x: x * 2))
print('Iter test:', result)  # Should be [2, 4, 6, 8]

# Test Let with simple case
target = {'a': 1, 'b': 2}
result = glom(target, Let({'total': T['a'] + T['b']}, {'sum': 'total'}))
print('Let test:', result)  # Should be {'sum': 3}

# Test ROOT
target = {'a': {'b': {'c': 1}}}
result = glom(target, {'a': {'root': ROOT}})
print('ROOT test:', result)  # Should be {'a': {'root': {'a': {'b': {'c': 1}}}}}
"
